"use strict";

const http = require("http");
const https = require("https");

const UA =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36";

const PAGE_HEADERS = {
  "user-agent": UA,
  accept:
    "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8",
  "accept-language": "en-US,en;q=0.9",
  "sec-ch-ua": '"Chromium";v="126", "Google Chrome";v="126", "Not;A=Brand";v="24"',
  "sec-ch-ua-mobile": "?0",
  "sec-ch-ua-platform": '"Windows"',
  "sec-fetch-dest": "document",
  "sec-fetch-mode": "navigate",
  "sec-fetch-site": "none",
  "upgrade-insecure-requests": "1",
};

const API_HEADERS = {
  "user-agent": UA,
  accept: "application/json, text/javascript, */*; q=0.01",
  "accept-language": "en-US,en;q=0.9",
  origin: "https://soundcloud.com",
  referer: "https://soundcloud.com/",
};

class Jar {
  constructor() {
    this.map = new Map();
  }
  absorb(setCookieLines) {
    const lines = Array.isArray(setCookieLines) ? setCookieLines : [];
    for (const line of lines) {
      const pair = String(line).split(";")[0];
      const i = pair.indexOf("=");
      if (i > 0) this.map.set(pair.slice(0, i).trim(), pair.slice(i + 1).trim());
    }
  }
  toString() {
    return [...this.map.entries()].map(([k, v]) => `${k}=${v}`).join("; ");
  }
}

function httpsGet(url, headers, timeoutMs = 20000, redirects = 5) {
  return new Promise((resolve, reject) => {
    let target;
    try {
      target = new URL(url);
    } catch {
      return reject(new Error(`Invalid URL: ${url}`));
    }
    const lib = target.protocol === "http:" ? http : https;
    const req = lib.get(
      {
        hostname: target.hostname,
        port: target.port || undefined,
        path: target.pathname + target.search,
        headers: headers || {},
        timeout: timeoutMs,
      },
      (res) => {
        const setCookie = res.headers["set-cookie"] || [];
        if (
          res.statusCode >= 300 &&
          res.statusCode < 400 &&
          res.headers.location &&
          redirects > 0
        ) {
          res.resume();
          const next = new URL(res.headers.location, target).toString();
          return resolve(
            httpsGet(next, headers, timeoutMs, redirects - 1).then((r) => ({
              ...r,
              setCookie: [...setCookie, ...(r.setCookie || [])],
            }))
          );
        }
        const chunks = [];
        res.on("data", (c) => chunks.push(c));
        res.on("end", () =>
          resolve({
            status: res.statusCode || 0,
            finalUrl: target.toString(),
            text: Buffer.concat(chunks).toString("utf8"),
            setCookie,
          })
        );
        res.on("error", reject);
      }
    );
    req.on("timeout", () => req.destroy(new Error("Request timed out")));
    req.on("error", reject);
  });
}

async function fetchWithTimeout(url, headers, timeoutMs = 20000) {
  return httpsGet(url, headers, timeoutMs, 5);
}

async function fetchPage(url, jar, hasData, attempts = 3) {
  let last = { status: 0, finalUrl: url, text: "" };
  for (let i = 0; i < attempts; i++) {
    try {
      const res = await fetchWithTimeout(url, {
        ...PAGE_HEADERS,
        cookie: jar.toString(),
      });
      jar.absorb(res.setCookie);
      last = { status: res.status, finalUrl: res.finalUrl, text: res.text };
      if (hasData(last.text)) return last;
    } catch {

    }
    await new Promise((r) => setTimeout(r, 700));
  }
  return last;
}

function parseHydration(html) {
  const m = String(html).match(/window\.__sc_hydration\s*=\s*(\[[\s\S]*?\]);/);
  if (!m) return null;
  try {
    const arr = JSON.parse(m[1]);
    const out = {};
    for (const item of arr) {
      if (item && item.hydratable) out[item.hydratable] = item.data;
    }
    return out;
  } catch {
    return null;
  }
}

let cachedClientId = null;
let clientIdPromise = null;

const CLIENT_ID_PATTERNS = [
  /client_id\s*:\s*"([A-Za-z0-9_-]{20,64})"/,
  /client_id\s*=\s*"([A-Za-z0-9_-]{20,64})"/,
  /"client_id"\s*,\s*"([A-Za-z0-9_-]{20,64})"/,
];

function bundleUrls(html) {
  const urls = new Set();
  const re = /https:\/\/a-v2\.sndcdn\.com\/assets\/[0-9A-Za-z\-._]+\.js/g;
  let m;
  while ((m = re.exec(String(html)))) urls.add(m[0]);
  return [...urls];
}

async function scrapeClientId(html, hydration) {
  if (cachedClientId) return cachedClientId;
  if (!clientIdPromise) {
    clientIdPromise = (async () => {
      const texts = await Promise.all(
        bundleUrls(html).map(async (u) => {
          try {
            const res = await fetchWithTimeout(u, {
              "user-agent": UA,
            });
            return res.status === 200 ? res.text : "";
          } catch {
            return "";
          }
        })
      );
      for (const text of texts) {
        for (const pattern of CLIENT_ID_PATTERNS) {
          const m = text.match(pattern);
          if (m) return m[1];
        }
      }
      if (hydration && hydration.apiClient && hydration.apiClient.id) {
        return hydration.apiClient.id;
      }
      return null;
    })();
  }
  cachedClientId = await clientIdPromise;
  if (!cachedClientId) clientIdPromise = null;
  return cachedClientId;
}

function presetBitrate(preset) {
  const m = String(preset || "").match(/(\d+)\s*k/i);
  return m ? parseInt(m[1], 10) : 0;
}

function rankTranscodings(transcodings) {
  const list = (transcodings || []).filter((t) => t && t.url && t.format);
  const progressive = list
    .filter((t) => t.format.protocol === "progressive")
    .sort((a, b) => presetBitrate(b.preset) - presetBitrate(a.preset));
  const hlsDirect = list
    .filter(
      (t) =>
        t.format.protocol === "hls" &&
        !/mpegurl/i.test(t.format.mime_type || "")
    )
    .sort((a, b) => {
      const q = (t) => (t.quality === "sq" ? 1 : 0);
      return q(b) - q(a) || presetBitrate(b.preset) - presetBitrate(a.preset);
    });
  const hlsMaster = list.filter(
    (t) =>
      t.format.protocol === "hls" && /mpegurl/i.test(t.format.mime_type || "")
  );
  return [...progressive, ...hlsDirect, ...hlsMaster];
}

async function resolveTranscoding(tc, track, clientId) {
  const sep = tc.url.includes("?") ? "&" : "?";
  let url = `${tc.url}${sep}client_id=${encodeURIComponent(clientId)}`;
  if (track.track_authorization) {
    url += `&track_authorization=${encodeURIComponent(track.track_authorization)}`;
  }
  if (track.secret_token) {
    url += `&secret_token=${encodeURIComponent(track.secret_token)}`;
  }
  const res = await fetchWithTimeout(url, API_HEADERS);
  if (res.status !== 200) return null;
  let json = null;
  try {
    json = JSON.parse(res.text);
  } catch {
    json = null;
  }
  return json && json.url ? json.url : null;
}

async function resolveStream(track, clientId) {
  if (!clientId || !track.media || !track.media.transcodings) return null;
  for (const tc of rankTranscodings(track.media.transcodings)) {
    try {
      const url = await resolveTranscoding(tc, track, clientId);
      if (url) {
        return {
          url,
          protocol: tc.format.protocol,
          mimeType: tc.format.mime_type || null,
          preset: tc.preset || null,
        };
      }
    } catch {

    }
  }
  return null;
}

const RESERVED_SEGMENTS = new Set([
  "you", "discover", "stream", "search", "upload", "settings", "messages",
  "notifications", "likes", "followers", "following", "tracks", "albums",
  "playlists", "reposts", "stats", "pro", "pages", "terms", "imprint",
]);

function parseTrackPath(input) {
  const s = String(input || "").trim();
  const m = s.match(/soundcloud\.com\/([A-Za-z0-9_-]+)\/([A-Za-z0-9_-]+)/i);
  if (m && !RESERVED_SEGMENTS.has(m[1].toLowerCase())) {
    return `https://soundcloud.com/${m[1]}/${m[2]}`;
  }
  if (/^https?:\/\/(on\.)?soundcloud\.com\//i.test(s)) return s;
  return null;
}

module.exports = async function fetchSelf(url) {
  const trackUrl = parseTrackPath(url);
  if (!trackUrl) {
    throw new Error("SoundCloud Error: Invalid SoundCloud track URL");
  }

  const jar = new Jar();
  const page = await fetchPage(
    trackUrl,
    jar,
    (h) => {
      const hy = parseHydration(h);
      return !!(hy && hy.sound && hy.sound.kind === "track");
    }
  );

  const hydration = parseHydration(page.text);
  const track = hydration && hydration.sound;
  if (!track || track.kind !== "track") {
    throw new Error(
      "SoundCloud Error: Track not found — it may be deleted, private, or SoundCloud changed its page format"
    );
  }
  if (!track.user && hydration.user) track.user = hydration.user;

  const clientId = await scrapeClientId(page.text, hydration);
  if (!clientId) {
    throw new Error("SoundCloud Error: Could not obtain a client_id");
  }

  const stream = await resolveStream(track, clientId);
  if (!stream || !stream.url) {
    throw new Error("SoundCloud Error: No playable stream found");
  }

  const streamUrl = stream.url;

  return {
    success: true,
    source: "SoundCloud",
    data: {
      title: track.title || "SoundCloud Track",
      author: (track.user && track.user.username) || null,
      thumbnail:
        (track.artwork_url || "").replace("-large.", "-t500x500.") || null,
      download: {
        video: streamUrl,
        videos: [{ quality: "audio", url: streamUrl }],
        audio: streamUrl,
        photos: [],
      },
    },
  };
};
